	EclipseNode fieldNode = null;
	if (annotationNode.up().getKind() == Kind.FIELD) {
		fieldNode = annotationNode.up();
	} else if (annotationNode.up().getKind() == Kind.TYPE_USE) {
		// A type-use annotation on a record component, e.g. `int @NonNull[] a`.
		EclipseNode tNode = annotationNode.directUp();
		EclipseNode up = tNode.directUp();
		if (up.getKind() == Kind.FIELD) fieldNode = up;
	}

	if (fieldNode != null) {
		//Check if this is a record and we need to generate the compact form constructor.
		EclipseNode typeNode = fieldNode.up();
		if (typeNode.getKind() == Kind.TYPE) {
			if (isRecord(typeNode)) {
				addCompactConstructorIfNeeded(typeNode, annotationNode);
			}
		}
	}

